import json
from typing import Any, Dict, List

CONFIG_ELEM_FIELDS = ('prcMonthFee', 'fixFee', 'fixValidity', 'containResource',
                      'theshold', 'outChargeMode', 'chargeStandard', 'outCharge', 'resourceType')

def _as_dict(v):
    return v if isinstance(v, dict) else {}

def _offers_of(obj):
    # 批量落地去重后的 config 结果：优先取 offers[]，旧单品平面对象包装为 1 品
    if not isinstance(obj, dict):
        return []
    offers = obj.get('offers')
    if isinstance(offers, list):
        return [o for o in offers if isinstance(o, dict)]
    return [obj] if obj.get('offer_id') or obj.get('offerId') or obj.get('plan_json') else []

def _scalar(v):
    if v is None:
        return ''
    if isinstance(v, (dict, list)):
        return ''
    s = str(v).strip()
    if not s or s in ('{', '}'):
        return ''
    return s

def _lookup(leaf, keys):
    for k in keys:
        v = _scalar(leaf.get(k) if isinstance(leaf, dict) else None)
        if v:
            return v
    return ''

def _collect_fees(optional, elems):
    # 计费叶子（参考 collectPayloadFeeValues 键对齐）
    if not isinstance(optional, dict):
        return
    print_c = _as_dict(optional.get('printContent'))
    acct = _as_dict(optional.get('acctMonth'))
    gprs = _as_dict(optional.get('billGprsCfg'))
    voice = _as_dict(optional.get('billVoiceCfg'))
    sms = _as_dict(optional.get('billSmsCfg'))
    def put(key, val):
        if val and key not in elems:
            elems[key] = val
    put('套餐档位(月费/固费)', _lookup(acct, ('fixFee',)) or _lookup(print_c, ('prcMonthFee',)))
    put('套餐有效期', _lookup(acct, ('fixValidity',)))
    put('包含资源(国内通用流量/语音/短信)', _lookup(print_c, ('containResource',)))
    put('套外流量-计费标准', _lookup(gprs, ('outChargeMode',)) or _lookup(print_c, ('chargeStandard',)))
    put('套外流量-阈值', _lookup(gprs, ('theshold',)))
    put('套外语音-计费', _lookup(voice, ('outCharge',)))
    put('套外短信-计费', _lookup(sms, ('outCharge',)))
    put('语音赠送量', _lookup(voice, ('theshold',)))
    put('短信赠送量', _lookup(sms, ('theshold',)))

def _base_name(plan):
    base = _as_dict(plan.get('baseInfo'))
    return _lookup(base, ('prodPrcName', 'name'))

def _plan_elements(plan):
    if not isinstance(plan, dict):
        return {}
    elems = {}
    # 配置落地形态：plan_json 顶层 optionalInfo/baseInfo
    _collect_fees(_as_dict(plan.get('optionalInfo')), elems)
    # 需求分析模板轨形态：payload.optionalInfo
    _collect_fees(_as_dict(_as_dict(plan.get('payload')).get('optionalInfo')), elems)
    # 套餐名（baseInfo 主信息叶子，配置报文口径）
    name = _base_name(plan)
    if not name:
        name = _base_name(_as_dict(plan.get('payload')))
    if name:
        elems.setdefault('套餐名称', name)
    return elems

async def main(args):
    raw = args.params['query_list']
    if not isinstance(raw, str):
        raw = json.dumps(raw, ensure_ascii=False)
    result_json = ''
    try:
        arr = json.loads(raw)
        if isinstance(arr, list) and arr:
            first = arr[0]
            if isinstance(first, dict):
                result_json = str(first.get('result_json') or '')
        elif isinstance(arr, dict):
            result_json = str(arr.get('result_json') or '')
    except Exception:
        result_json = ''
    if not result_json:
        result_json = raw
    out_list = []
    try:
        obj = json.loads(result_json)
    except Exception:
        obj = None
    if isinstance(obj, dict):
        for o in _offers_of(obj):
            plan = _as_dict(o.get('plan_json'))
            if not isinstance(plan, dict) and isinstance(o.get('payload'), dict):
                plan = _as_dict(o.get('payload'))
            elems = _plan_elements(plan)
            item = {'offer_id': str(o.get('offer_id') or o.get('offerId') or ''),
                    'offer_name': str(o.get('offer_name') or elems.get('套餐名称') or '')}
            item['config_elements'] = elems
            out_list.append(item)
    config_elements = json.dumps(out_list, ensure_ascii=False)
    available = '1' if out_list and any(it['config_elements'] for it in out_list) else '0'
    ret: Output = {
        'config_elements': config_elements,
        'config_elements_available': available
    }
    return ret

from typing import Any, Dict

def _csv(v):
    # offers 入参可能是 JSON 数组字符串或已归一数组，拍平为 offer_id 逗号串
    import json as _json
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return ''
        try:
            v = _json.loads(s)
        except Exception:
            v = s
    if isinstance(v, dict) and isinstance(v.get('offers'), list):
        v = v['offers']
    if not isinstance(v, list):
        return ''
    ids = []
    for o in v:
        oid = str((o or {}).get('offer_id') or '') if isinstance(o, dict) else ''
        if oid:
            ids.append(oid)
    return ','.join(ids)

